"""Presentation-only global block using the established local chart library."""

CONTEXT_JS = r'''
(()=>{
 const original=window.renderTechnical;
 const f=v=>v===null||v===undefined||v===''?'UNAVAILABLE':typeof v==='number'?v.toLocaleString('en-IN',{maximumFractionDigits:4}):String(v);
 window.renderTechnical=(day,t,c)=>{
  original(day,t,c);
  const panel=document.getElementById('market-context');
  // Replace superseded global rows, preserving independent NSE and H10 context.
  const currentKeys=new Set((window.TECH06_GLOBAL?.context[day]||[]).map(r=>r.series));
  for(const tr of panel.querySelectorAll('tr')){const key=tr.firstElementChild?.textContent.split(' / ')[0];if(currentKeys.has(key))tr.remove()}
  panel.querySelector('#global-recovered-context')?.remove();
  const section=document.createElement('section');section.id='global-recovered-context';section.dataset.selectedDate=day;
  const inv=window.TECH06_GLOBAL?.status.find(r=>r.series==='GIFT_NIFTY');
  const coverage=document.createElement('p');coverage.id='gift-current-coverage';coverage.textContent='GIFT / SGX Nifty · generic provider quotation · '+(inv?.accepted_daily_observations??0)+' daily / '+(inv?.accepted_minute_observations??0)+' sampled minute observations; no verified contract or expiry.';section.append(coverage);
  const title=document.createElement('h3');title.textContent='Recovered global block · Indian checkpoints';section.append(title);
  const note=document.createElement('p');note.textContent='Original 16 requests and separate four-request GIFT quotation scope completed once. Values below are retrospective; historical delivery is unverified. Provider units/benchmark definitions remain unverified. Treasury yields are nominal par constant-maturity yields; changes and 10Y−2Y are in basis points. US Tech 100 retains its provider identity. GIFT is a generic quotation with no verified futures expiry.';section.append(note);
  const link=document.createElement('a');link.href='../global-market.html';link.textContent='Open global history, coverage and checkpoint review';section.append(link);
  const rows=(window.TECH06_GLOBAL?.context[day]||[]);
  const table=document.createElement('table');let tr=document.createElement('tr');
  for(const label of ['Series / source','Phase','Verified value','Retrospective value / units','Change (bp)','Provider direction / change %','Observed / age','Evidence / gap']){let th=document.createElement('th');th.textContent=label;tr.append(th)}table.append(tr);
  for(const r of rows){let tr=document.createElement('tr');for(const val of [r.label+' / '+r.channel,r.phase,f(r.verified_value),f(r.retrospective_value)+' '+r.units,f(r.change_bp),f(r.direction)+' / '+f(r.change_pct),f(r.observation_date)+' / '+f(r.age_minutes)+' min',r.reason]){let td=document.createElement('td');td.textContent=val;td.title=(r.source_file||'')+' | '+(r.source_sha256||'')+' | '+(r.source_observation_timestamp||r.observation_convention_ist||'timestamp unavailable')+' | '+(r.stale_status||'')+' | change base '+(r.change_base_timestamp||'');tr.append(td)}table.append(tr)}
  section.append(table);panel.append(section);
 };
})();
'''

PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>TECH-06 · global market block</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>body{background:#111922;color:#dfe7ef;font:14px system-ui;margin:24px;max-width:1600px}a{color:#9bc4ee}h1{font-size:24px}h2{font-size:18px;margin-top:28px}p{max-width:1150px;line-height:1.6}select,button{background:#202c38;color:inherit;border:1px solid #536171;padding:8px;margin:5px 15px 5px 5px}label{display:inline-block}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:8px;border-bottom:1px solid #344150;text-align:left;vertical-align:top}th{position:sticky;top:0;background:#111922}.scroll{overflow:auto;max-height:430px}small,.muted{color:#aab8c4}.metric{display:inline-block;margin-right:40px;line-height:2}.metric b{font-size:21px;display:block}#quote-chart{height:320px}#yield-chart,#spread-chart{height:240px}.axis-label{margin:4px 0;color:#aab8c4}#quote-readout{min-height:42px;margin-top:10px}.note{border-left:3px solid #9bc4ee;padding-left:16px}#cutoff-description{font-weight:600}details{margin-top:16px}header{border-bottom:1px solid #344150;padding-bottom:15px}</style></head><body>
<header><a href="index.html">Technical charts</a><h1>Global market block · recovered history</h1>
<p>Study: 1 December 2025–30 October 2026. The original 16 requests and the separately authorized four GIFT quotation requests completed once. Retained Dow history and official US Treasury par yields are included separately.</p>
<div class="metric"><b>16 + 4 / 20</b>approved requests succeeded · no repeats</div><div class="metric"><b id="daily-count"></b>accepted new daily bars · 2 quarantined</div><div class="metric"><b id="minute-count"></b>accepted new minute bars</div><div class="metric"><b>0</b>verified historical decision-time values</div></header>
<p class="note">Retrospective values stay separate from verified values. An earlier candle start or a scheduled quotation/release time does not prove historical availability. All bar selection uses a strict cutoff; no carry-forward across unrequested minute windows. Existing stock indicators and subsector indices are preserved.</p>
<h2>Required components · individual status</h2><div class="scroll"><table id="components"></table></div>
<h2>Indian checkpoint inspection</h2><label>Indian session <select id="session"></select></label><label>Checkpoint <select id="phase"><option value="PREOPEN">Pre-open · 09:15 IST</option><option value="POSTCLOSE">Post-close · 18:00 IST</option></select></label><p id="cutoff-description"></p>
<div class="scroll"><table id="checkpoint"></table></div>
<p class="muted">Age is measured from the provider bucket end or the approximate Treasury quote convention. It is not a delivery delay. Dow/S&amp;P cash-session interpretation is quarantined. Daily provider buckets are not certified exchange-session closes. Treasury values are current vintage; their approximate 15:30 New York quote convention is not a publication timestamp. All daily changes compare consecutive source observations, with the base date retained.</p>
<h2>Provider price history · original instrument identities</h2>
<label>Series <select id="series"></select></label><label>Returned interval / window <select id="window"></select></label><p id="coverage"></p>
<div class="axis-label">Y: provider quote units · denomination / benchmark definition unverified</div><div id="quote-chart"></div><div class="axis-label" id="quote-axis">X: provider IST daily bucket date</div><div id="quote-readout" aria-live="polite"></div>
<p class="muted">Source: exact retained Upstox V3 responses, plus retained Upstox Dow. Sparse candles are displayed without invented bars. US Tech 100 is the provider label; it is not certified as Nasdaq Composite or a Nasdaq futures contract. GIFT Nifty is a generic quotation with no verified futures contract or expiry. Oil quotes are not asserted to be spot assessments or identified futures. Quarantined daily candles: WTI, 18 June 2026 (close exceeds high); GIFT, 19 July 2026 (open exceeds high).</p>
<h2>Official Treasury yields · 2-year, 10-year and 30-year</h2><div class="axis-label">Y: nominal par yield · percent per annum</div><div id="yield-chart"></div><div class="axis-label">X: US observation date · 2Y blue, 10Y sand, 30Y teal</div>
<h2>Treasury curve · 10Y minus 2Y</h2><div class="axis-label">Y: yield spread · basis points · (10Y yield − 2Y yield) × 100</div><div id="spread-chart"></div><div class="axis-label">X: US observation date</div>
<p id="treasury-coverage"></p><p class="muted">Source: two annual US Treasury nominal par-yield XML files, filtered to 20 November 2025–30 October 2026. November supplies a checkpoint/change baseline. Indicative bid-side quotations near 15:30 America/New_York, not live tradable yields or bond ETF prices. Lines connect observed dates for display; no intervening observations are generated.</p>
<details><summary>Evidence, source definitions and remaining authorization blockers</summary><p><a href="../narrowed-global/EXECUTION_REPORT.md">Execution and integration report</a> · <a href="../narrowed-global/CANDLE_COVERAGE.csv">Per-request coverage</a> · <a href="../narrowed-global/INDIAN_CHECKPOINT_CONTEXT.csv">Checkpoint ledger</a> · <a href="../narrowed-global/TREASURY_YIELDS_AND_SPREAD.csv">Yields, changes and spread</a> · <a href="../narrowed-global/SOURCE_AND_LICENSE_REVIEW.md">Exact-instrument source and licensing review</a> · <a href="../narrowed-global/additional/GIFT_EXECUTION_LEDGER.json">Completed GIFT quotation requests</a></p></details>
<p><small>TradingView Lightweight Charts™ 5.0.9 · local assets · Apache-2.0. <a href="stocks/assets/LICENSE-lightweight-charts.txt">License</a>. No remote chart requests.</small></p>
<script src="lightweight-charts-5.0.9.js"></script><script src="global-market-data.js"></script><script src="global-minute-data.js"></script><script>
(()=>{
 const D=window.TECH06_GLOBAL,B=window.TECH06_GLOBAL_BARS,L=LightweightCharts;
 const el=id=>document.getElementById(id),f=v=>v==null||v===''?'UNAVAILABLE':typeof v==='number'?v.toLocaleString('en-IN',{maximumFractionDigits:4}):String(v);
 el('daily-count').textContent=f(B.filter(r=>r.unit==='days'&&r.series!=='DJIA').length);el('minute-count').textContent=f(B.filter(r=>r.unit==='minutes').length);
 function table(id,columns,rows){const t=el(id);t.replaceChildren();let tr=document.createElement('tr');for(const [label] of columns){let th=document.createElement('th');th.textContent=label;tr.append(th)}t.append(tr);for(const r of rows){let tr=document.createElement('tr');for(const [,key] of columns){let td=document.createElement('td');td.textContent=f(r[key]);if(r.source_file)td.title=r.source_file+' | '+r.source_sha256+' | '+(r.source_observation_timestamp||r.observation_convention_ist||'');tr.append(td)}t.append(tr)}}
 table('components',[['Component','label'],['Status','status'],['Accepted daily values','accepted_daily_observations'],['Sampled minute values','accepted_minute_observations'],['First','first_date'],['Last','last_date'],['Evidence / remaining gap','limitation']],D.status);
 for(const date of D.sessions)el('session').add(new Option(date,date));el('session').value='2026-06-19';
 function inspect(day=el('session').value,phase=el('phase').value){el('session').value=day;el('phase').value=phase;const rows=(D.context[day]||[]).filter(r=>r.phase===phase);el('cutoff-description').textContent=day+' · '+(phase==='PREOPEN'?'09:15':'18:00')+' Asia/Kolkata · verified decision-time values: 0';table('checkpoint',[['Series / channel','display'],['Verified value','verified_value'],['Retrospective value','retrospective_value'],['Units','units'],['Change (bp)','change_bp'],['Provider direction','direction'],['Change (%)','change_pct'],['Observed date','observation_date'],['Age (min)','age_minutes'],['Freshness','stale_status'],['Evidence / gap','reason']],rows.map(r=>({...r,display:r.label+' / '+r.channel})));if(window.GLOBAL_REVIEW){GLOBAL_REVIEW.selectedDate=day;GLOBAL_REVIEW.selectedPhase=phase}}
 const opt={layout:{background:{color:'#111922'},textColor:'#dfe7ef'},grid:{vertLines:{color:'#24313d'},horzLines:{color:'#24313d'}},timeScale:{timeVisible:false},localization:{locale:'en-IN'}};
 const quote=L.createChart(el('quote-chart'),opt),yc=L.createChart(el('yield-chart'),opt),sc=L.createChart(el('spread-chart'),opt);
 const cand=quote.addSeries(L.CandlestickSeries,{upColor:'#54bca8',downColor:'#dd8e8e',borderVisible:false,wickUpColor:'#54bca8',wickDownColor:'#dd8e8e'});
 for(const [key,title,color] of [['UST2Y','2-year','#9bc4ee'],['UST10Y','10-year','#d7cba8'],['UST30Y','30-year','#54bca8']]){let s=yc.addSeries(L.LineSeries,{title,color});s.setData(D.treasury.map(r=>r[key]==null?{time:r.date}:{time:r.date,value:r[key]}))}
 const spread=sc.addSeries(L.LineSeries,{title:'10Y−2Y · bp',color:'#9bc4ee'});spread.setData(D.treasury.map(r=>r.spread_10y_2y_bp==null?{time:r.date}:{time:r.date,value:r.spread_10y_2y_bp}));spread.createPriceLine({price:0,color:'#536171',lineWidth:1,lineStyle:2,axisLabelVisible:true});yc.timeScale().fitContent();sc.timeScale().fitContent();
 el('treasury-coverage').textContent=D.treasury.length+' US observation dates retained, including November baseline. Yield changes: (current yield − previous source observation) × 100 basis points. Spread change: current spread − previous same-date spread, in basis points.';
 for(const key of ['USDINR','BRENT','WTI','US_TECH100','DJIA','GIFT_NIFTY'])el('series').add(new Option(D.status.find(r=>r.series===key).label,key));
 let active=[];
 function windows(){el('window').replaceChildren();const rows=B.filter(r=>r.series===el('series').value);const numbers=[...new Set(rows.map(r=>r.number))];for(const n of numbers){let a=rows.filter(r=>r.number===n);el('window').add(new Option((a[0].unit==='days'?'Daily · ':'1-minute · ')+a[0].date+' → '+a.at(-1).date+' · request '+n,String(n)))}plot()}
 function plot(){active=B.filter(r=>r.series===el('series').value&&String(r.number)===el('window').value);const minute=active[0]?.unit==='minutes';const fmt=v=>typeof v==='number'?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v*1000)):typeof v==='string'?v:JSON.stringify(v);quote.applyOptions({timeScale:{timeVisible:minute,tickMarkFormatter:minute?fmt:undefined},localization:{timeFormatter:minute?fmt:undefined}});cand.setData(active.map(r=>({time:minute?r.time:r.date,open:r.open,high:r.high,low:r.low,close:r.close})));quote.timeScale().fitContent();el('coverage').textContent=active.length+' structurally accepted provider bars · '+(minute?'sample window only; no complete-quarter coverage':'provider date buckets; US exchange-session mapping unverified')+' · historical delivery and units unverified';el('quote-axis').textContent=minute?'X: candle start · date/time in Asia/Kolkata':'X: provider IST daily bucket date';el('quote-readout').textContent='Inspect a candle to see its original timestamp and source. No value in this plot is labeled as verified decision-time data.';if(window.GLOBAL_REVIEW)GLOBAL_REVIEW.activeBars=active}
 quote.subscribeCrosshairMove(p=>{if(p.time===undefined)return;const r=active.find(r=>r.unit==='minutes'?r.time===p.time:r.date===p.time);if(!r)return;el('quote-readout').textContent=r.timestamp+' · O '+f(r.open)+' H '+f(r.high)+' L '+f(r.low)+' C '+f(r.close)+' · '+r.source_file+' · retrospective only';if(D.sessions.includes(r.date))inspect(r.date)});
 let syncing=false;for(const [a,b] of [[yc,sc],[sc,yc]])a.timeScale().subscribeVisibleLogicalRangeChange(range=>{if(range&&!syncing){syncing=true;b.timeScale().setVisibleLogicalRange(range);syncing=false}});
 el('session').onchange=()=>inspect();el('phase').onchange=()=>inspect();el('series').onchange=windows;el('window').onchange=plot;
 window.GLOBAL_REVIEW={data:D,bars:B,inspect,plot,windows,selectedDate:null,selectedPhase:null,activeBars:[],charts:{quote,yields:yc,spread:sc}};
 windows();inspect();window.addEventListener('resize',()=>{quote.resize(el('quote-chart').clientWidth,320);yc.resize(el('yield-chart').clientWidth,240);sc.resize(el('spread-chart').clientWidth,240)});
})();
</script></body></html>'''
